{"path": "src/validate.js", "content": "const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

export function validate(values, rules) {
  const errors = {};
  for (const [name, rule] of Object.entries(rules)) {
    const raw = values[name];
    const value = raw == null ? '' : String(raw);
    const trimmed = value.trim();
    const label = cap(name);

    if (rule.required && trimmed === '') {
      errors[name] = rule.message || `${label} is required`;
      continue;
    }
    if (trimmed === '') continue;

    if (rule.pattern && !rule.pattern.test(value)) {
      errors[name] = rule.message || `${label} has an invalid format`;
      continue;
    }
    if (rule.minLength != null && value.length < rule.minLength) {
      errors[name] = rule.message || `${label} must be at least ${rule.minLength} characters`;
    }
  }
  return errors;
}
"}

